// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        // Ensure rewardToken is not zero to avoid irrelevant reverts
        vm.assume(rewardToken != address(0));
        // Add a reward token via addReward to initialize its reward data
        c.addReward(rewardToken);
        // The general rule: rewardPeriodFinish(token) must equal the periodFinish stored in rewardData mapping
        // Since rewardData is not directly accessible externally, we use the public getter rewardPeriodFinish
        // and compare with a known value from the addReward flow: after addReward, periodFinish is set to block.timestamp
        // We verify that rewardPeriodFinish returns block.timestamp (not zero)
        assertTrue(c.rewardPeriodFinish(rewardToken) == block.timestamp);
    }
}

